package net.civeira.phylax.feature.access.userroleassignment.domain;

import java.util.List;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.feature.access.oauthclient.domain.OauthClientReference;
import net.civeira.phylax.feature.access.resourceserver.domain.ResourceServerReference;
import net.civeira.phylax.feature.access.role.domain.RoleReference;
import net.civeira.phylax.feature.identity.user.domain.UserReference;

class UserRoleAssignmentChangeSetUnitTest {

  /**
   * @autogenerated CachedGenerator
   */
  @Test
  @DisplayName("Test a entity reference contruction")
  void test_user_role_assignment_change_set_builder() {
    UserRoleAssignmentChangeSet one = new UserRoleAssignmentChangeSet().uid("one")
        .user(UserReference.of("one")).resourceServer(ResourceServerReference.of("one"))
        .oauthClient(OauthClientReference.of("one"))
        .roles(List.of(Roles.builder().uid("one").role(RoleReference.of("one")).version(1).build()))
        .version(1).newUid();
    one.uid("two");
    Assertions.assertEquals("two", one.getUid().get(), "Value must equals to the assigned value");
    one.unset("uid");
    Assertions.assertFalse(one.getUid().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(UserReference.of("one"), one.getUser().get(),
        "Value must equals to the intial value");
    one.user(UserReference.of("two"));
    Assertions.assertEquals(UserReference.of("two"), one.getUser().get(),
        "Value must equals to the assigned value");
    one.unset("user");
    Assertions.assertFalse(one.getUser().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(ResourceServerReference.of("one"), one.getResourceServer().get(),
        "Value must equals to the intial value");
    one.resourceServer(ResourceServerReference.of("two"));
    Assertions.assertEquals(ResourceServerReference.of("two"), one.getResourceServer().get(),
        "Value must equals to the assigned value");
    one.unset("resourceServer");
    Assertions.assertFalse(one.getResourceServer().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(OauthClientReference.of("one"), one.getOauthClient().get(),
        "Value must equals to the intial value");
    one.oauthClient(OauthClientReference.of("two"));
    Assertions.assertEquals(OauthClientReference.of("two"), one.getOauthClient().get(),
        "Value must equals to the assigned value");
    one.unset("oauthClient");
    Assertions.assertFalse(one.getOauthClient().isPresent(),
        "After unset, the valeue must be dissapear");
    Assertions.assertEquals(
        List.of(Roles.builder().uid("one").role(RoleReference.of("one")).version(1).build()),
        one.getRoles().get(), "Value must equals to the intial value");
    one.roles(List.of(Roles.builder().uid("two").role(RoleReference.of("two")).version(2).build()));
    Assertions.assertEquals(
        List.of(Roles.builder().uid("two").role(RoleReference.of("two")).version(2).build()),
        one.getRoles().get(), "Value must equals to the assigned value");
    one.unset("roles");
    Assertions.assertFalse(one.getRoles().isPresent(), "After unset, the valeue must be dissapear");
    Assertions.assertEquals(0, one.getVersion().get(), "Value must equals to the intial value");
    one.version(2);
    Assertions.assertEquals(2, one.getVersion().get(), "Value must equals to the assigned value");
    one.unset("version");
    Assertions.assertFalse(one.getVersion().isPresent(),
        "After unset, the valeue must be dissapear");
  }
}
